//! Per-Run state types shared by [`engine`](super::engine) and the [`app`]
//! command surface.

use serde::{Deserialize, Serialize};

use mixd_providers::Usage;

/// Opaque Run identifier (UUIDv4, generated by the storage layer on insert).
pub type RunId = uuid::Uuid;

/// Token and cost summary for a Run, persisted on its `runs` row and streamed
/// in `usage` events.
///
/// The four token counts are cumulative across every turn (what was actually
/// billed), while `context_tokens` is the most recent turn's prompt size — the
/// figure the context meter needs. They deliberately live in one shape so the
/// live event, the persisted row, and the history replay all read the same
/// fields.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RunUsage {
    pub input_tokens: u64,
    pub output_tokens: u64,
    pub cache_read_tokens: u64,
    pub cache_write_tokens: u64,
    /// Prompt tokens of the latest turn, or `0` before the first turn.
    pub context_tokens: u64,
    /// The model's context window, or `0` when the provider did not report one.
    pub context_window: u32,
    /// Estimated spend in USD from [`crate::pricing`]; `None` when the model is
    /// not in the price table.
    pub estimated_cost_usd: Option<f64>,
}

impl RunUsage {
    /// Fold one turn's provider usage into the running totals.
    pub fn record(&mut self, usage: &Usage) {
        self.input_tokens = self.input_tokens.saturating_add(usage.input_tokens);
        self.output_tokens = self.output_tokens.saturating_add(usage.output_tokens);
        self.cache_read_tokens = self
            .cache_read_tokens
            .saturating_add(usage.cache_read_tokens);
        self.cache_write_tokens = self
            .cache_write_tokens
            .saturating_add(usage.cache_write_tokens);
        // Providers that report the prompt size explicitly win; otherwise the
        // three input buckets are the closest honest approximation (an
        // Anthropic-shaped Usage). Never include output tokens here: they are
        // not part of the prompt that occupied the window.
        self.context_tokens = usage.context_tokens.unwrap_or_else(|| {
            usage
                .input_tokens
                .saturating_add(usage.cache_read_tokens)
                .saturating_add(usage.cache_write_tokens)
        });
    }

    /// The cumulative counts in the provider's own shape, for pricing.
    pub fn as_usage(&self) -> Usage {
        Usage {
            input_tokens: self.input_tokens,
            output_tokens: self.output_tokens,
            cache_read_tokens: self.cache_read_tokens,
            cache_write_tokens: self.cache_write_tokens,
            context_tokens: Some(self.context_tokens),
        }
    }

    /// Total billed tokens (input + output + cache).
    pub fn total_tokens(&self) -> u64 {
        self.input_tokens
            .saturating_add(self.output_tokens)
            .saturating_add(self.cache_read_tokens)
            .saturating_add(self.cache_write_tokens)
    }
}

/// Lifecycle states a Run can occupy.
///
/// The set mirrors the Docker edition's documented states and is treated as
/// the single source of truth across storage, engine, and Tauri command
/// surface.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RunStatus {
    Queued,
    Running,
    WaitingApproval,
    BudgetExtensionPending,
    Interrupted,
    Failed,
    Cancelled,
    Completed,
}

impl RunStatus {
    pub fn as_str(&self) -> &'static str {
        match self {
            RunStatus::Queued => "queued",
            RunStatus::Running => "running",
            RunStatus::WaitingApproval => "waiting_approval",
            RunStatus::BudgetExtensionPending => "budget_extension_pending",
            RunStatus::Interrupted => "interrupted",
            RunStatus::Failed => "failed",
            RunStatus::Cancelled => "cancelled",
            RunStatus::Completed => "completed",
        }
    }

    pub fn is_terminal(&self) -> bool {
        matches!(
            self,
            RunStatus::Completed
                | RunStatus::Failed
                | RunStatus::Cancelled
                | RunStatus::Interrupted
        )
    }
}

/// Public-facing Run snapshot used by the Tauri command surface and the
/// SSE-equivalent event stream.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RunView {
    pub id: RunId,
    pub conversation_id: uuid::Uuid,
    pub mode: String,
    pub status: RunStatus,
    pub model_id: String,
    pub step_count: u32,
    pub tool_call_count: u32,
    /// Tool calls that ended with an error (including denied approvals).
    /// Collapsed transcripts only showed the success count, so a failed edit or
    /// a non-zero command was invisible unless the accordion was opened.
    #[serde(default)]
    pub failed_tool_count: u32,
    pub started_at: chrono::DateTime<chrono::Utc>,
    pub updated_at: chrono::DateTime<chrono::Utc>,
    pub summary: String,
    pub budget: serde_json::Value,
    /// Cumulative token/spend summary, written when the Run reaches a terminal
    /// status. `None` for rows persisted before this field existed.
    #[serde(default)]
    pub usage: Option<RunUsage>,
    /// Terminal error text when the Run failed (provider error, context
    /// overflow, …). `None` for a Run that did not fail. Surfaced so the UI can
    /// explain why a Run stopped instead of leaving a silent spinner.
    #[serde(default)]
    pub error: Option<String>,
    /// True when the persisted event log exceeds
    /// `crate::runs::events::MAX_REPLAY_EVENTS`. The transcript list can warn
    /// without loading the whole event window first.
    #[serde(default)]
    pub replay_truncated: bool,
}

pub type RunState = RunView;
